mapper.select:
SElECT
t.time_table_key AS timeTableKey,
t.start_time AS startTime,
CONCAT(cc.class_name, ' ', uc.unit_name) AS className,
COUNT(ta.student_id) AS countStudent,
u.user_name AS userName
FROM erp_time_table t
LEFT JOIN erp_time_table_assign ta ON t.time_table_key = ta.time_table_key
LEFT JOIN erp_class_code cc ON t.class_key = cc.class_key
LEFT JOIN erp_unit_code uc ON t.unit_key = uc.unit_key
JOIN erp_user u ON t.user_code = u.user_code
WHERE t.yy = #{year}
AND t.mm = #{month}
AND t.dayname = #{dayname}

    AND t.user_code = #{userCode}

AND u.center_code = #{centerCode}
GROUP BY t.time_table_key, t.start_time, cc.class_name, uc.unit_name, u.user_name
ORDER BY startTime ASC;

SELECT *
FROM erp_class_week
WHERE year = #{year}
  AND month = #{month}
  AND center_code = #{centerCode}
ORDER BY week

mapper.update:
UPDATE erp_class_week
SET mon        = #{mon},
    tue        = #{tue},
    wed        = #{wed},
    thu        = #{thu},
    fri        = #{fri},
    sat        = #{sat},
    sun        = #{sun},
    updated_at = SYSDATETIME()
WHERE year = #{year}
  AND month = #{month}
  AND week = #{week}
  AND center_code = #{centerCode}

mapper.select:
SELECT py.class_key   AS classKey,
       py.unit_key    AS unitKey,
       main.unit_name AS unitName,
       1              AS orderFlag
FROM erp_person_year py
         JOIN erp_unit_code main ON py.unit_key = main.unit_key
WHERE center_code = #{centerCode}
  AND yy = #{yy}
  AND mm = #{mm}
  AND py.class_key = #{classKey}

UNION ALL

SELECT py.class_key    AS classKey,
       py.sub_unit_key AS unitKey,
       sub.unit_name   AS unitName,
       2               AS orderFlag
FROM erp_person_year py
         JOIN erp_unit_code sub ON py.sub_unit_key = sub.unit_key
WHERE center_code = #{centerCode}
  AND yy = #{yy}
  AND mm = #{mm}
  AND py.class_key = #{classKey}
ORDER BY orderFlag ASC;

SELECT py.class_key AS classKey, py.unit_key AS unitKey, main.unit_name AS unitName, 1 AS orderFlag FROM erp_person_year py JOIN erp_unit_code main ON py.unit_key = main.unit_key WHERE center_code = #{centerCode} AND (yy * 100 + mm) BETWEEN (#{startYear} * 100 + #{startMonth}) AND (#{endYear} * 100 + #{endMonth}) AND py.class_key = #{classKey}
UNION ALL
SELECT py.class_key AS classKey, py.sub_unit_key AS unitKey, sub.unit_name AS unitName, 2 AS orderFlag FROM erp_person_year py JOIN erp_unit_code sub ON py.sub_unit_key = sub.unit_key WHERE center_code = #{centerCode} AND (yy * 100 + mm) BETWEEN (#{startYear} * 100 + #{startMonth}) AND (#{endYear} * 100 + #{endMonth}) AND py.class_key = #{classKey} ORDER BY orderFlag ASC;

