mapper.select:
SELECT
tc.time_table_key as timeTableKey,
tc.time_table_label as classLabel,
t.class_key as classKey
FROM ERP_TIME_TABLE t
JOIN ERP_TIME_TABLE_CODE tc ON t.time_table_key = tc.time_table_key
WHERE YY = #{yy}
AND MM = #{mm}

    AND LEN(t.class_key) > #{count}


    AND t.user_code = #{userCode}

ORDER BY CHARINDEX(dayname, 'mon,tue,wed,thu,fri,sat,sun');

SELECT
tc.time_table_key as timeTableKey,
tc.time_table_label as classLabel,
t.class_key as classKey
FROM ERP_TIME_TABLE t
JOIN ERP_TIME_TABLE_CODE tc ON t.time_table_key = tc.time_table_key
WHERE YY = #{yy}
AND MM = #{mm}
AND LEN(t.class_key) > 1
AND dayname = #{dayname}

    AND t.user_code = #{userCode}

ORDER BY CHARINDEX(dayname, 'mon,tue,wed,thu,fri,sat,sun');

mapper.update:
UPDATE erp_time_table_assign
SET class_key = #{classKey},
    unit_key  = #{unitKey}
WHERE time_table_key = #{timeTableKey}
  AND student_id = #{studentId}

mapper.select:
SELECT t.time_table_key as timeTableKey,
tc.time_table_label as classLabel,
t.class_key as classKey,
t.unit_key as unitKey
FROM erp_time_table t
JOIN erp_time_table_code tc ON t.time_table_key = tc.time_table_key
WHERE yy = #{yy}
AND mm = #{mm}
AND dayName = #{dayName}
AND center_code = #{centerCode}

    AND user_code = #{userCode}

ORDER BY t.start_time ASC

SELECT ac.after_class_key  AS afterClassKey,
       ac.content          AS content,
       t.time_table_key    AS timeTableKey,
       tc.time_table_label AS timeTableLabel,
       u.user_name         AS userName
FROM erp_after_class ac
         JOIN erp_time_table t ON ac.class_key = t.class_key AND ac.unit_key = t.unit_key
         JOIN erp_user u ON t.user_code = u.user_code
         JOIN erp_time_table_code tc ON t.time_table_key = tc.time_table_key
WHERE ac.unit_key = #{unitKey}
  AND t.class_key = #{classKey}
  AND ac.week = #{week}
  AND t.time_table_key = #{timeTableKey}

WITH base AS (SELECT s.student_id, s.yy, s.mm, s.time_table_key, t.class_key, t.unit_key, question1, question2, question3, question4, question5, question6, question7, question8 FROM erp_monthly_score s JOIN erp_time_table t ON s.time_table_key = t.time_table_key WHERE s.student_id = #{studentId} AND s.yy = #{yy} AND s.mm = #{mm} AND s.time_table_key = #{timeTableKey}), merged AS (SELECT f.number, f.difficultly, f.correct_ment, f.wrong_ment, CASE WHEN f.number = 1 THEN b.question1 WHEN f.number = 2 THEN b.question2 WHEN f.number = 3 THEN b.question3 WHEN f.number = 4 THEN b.question4 WHEN f.number = 5 THEN b.question5 WHEN f.number = 6 THEN b.question6 WHEN f.number = 7 THEN b.question7 WHEN f.number = 8 THEN b.question8 END AS score, b.class_key, b.unit_key, b.student_id FROM base b JOIN erp_monthly_feedback f ON f.yy = b.yy AND f.class_key = b.class_key AND f.unit_key = b.unit_key) SELECT st.student_name AS studentName, mc.top_comment AS topComment, mc.bottom_comment AS bottomComment, (SELECT TOP 1 correct_ment FROM merged WHERE score = 1 ORDER BY difficultly DESC) AS topCorrectMent,
(SELECT TOP 1 wrong_ment FROM merged WHERE score = 0 ORDER BY difficultly DESC) AS topWrongMent
FROM merged m LEFT JOIN erp_monthly_comment mc ON m.class_key = mc.class_key AND m.unit_key = mc.unit_key LEFT JOIN erp_student st ON m.student_id = st.student_id GROUP BY st.student_name, mc.top_comment, mc.bottom_comment;

SELECT *
FROM erp_monthly_result
WHERE student_id = #{studentId}
  AND time_table_key = #{timeTableKey}
  AND yy = #{yy}
  AND mm = #{mm}

SELECT s.student_id, st.student_name, s.time_table_key, mr.top_comment, mr.bottom_comment, mr.feedback, f.number AS part, CASE f.number WHEN 1 THEN s.question1 WHEN 2 THEN s.question2 WHEN 3 THEN s.question3 WHEN 4 THEN s.question4 WHEN 5 THEN s.question5 WHEN 6 THEN s.question6 WHEN 7 THEN s.question7 WHEN 8 THEN s.question8 END AS score,
f.competency, f.difficultly
FROM erp_monthly_score s JOIN erp_student st ON s.student_id = st.student_id JOIN erp_time_table t ON s.time_table_key = t.time_table_key JOIN erp_monthly_feedback f ON f.class_key = t.class_key AND f.unit_key = t.unit_key LEFT JOIN erp_monthly_result mr ON mr.time_table_key = t.time_table_key AND mr.student_id = s.student_id
WHERE s.student_id = #{studentId} AND s.yy = #{yy} AND s.mm = #{mm} AND s.time_table_key = #{timeTableKey}
ORDER BY f.number ASC;

SELECT
tc.time_table_key AS timeTableKey,
tc.time_table_label AS classLabel,
t.class_key AS classKey,
t.unit_key AS unitKey
FROM ERP_TIME_TABLE t
JOIN ERP_TIME_TABLE_CODE tc ON t.time_table_key = tc.time_table_key
WHERE t.yy = #{yy}
AND t.mm = #{mm}
AND LEN(t.class_key) = 1

    AND t.user_code = #{userCode}

ORDER BY tc.time_table_key;

SELECT COUNT(*)
FROM erp_infant_send_history
